import { LucideIcon } from "lucide-react";

interface StatProps {
  label: string;
  value: string;
  change?: string;
  icon: LucideIcon;
  tone: "blue" | "sky" | "navy" | "amber" | "red" | string;
}

const tones: Record<string, string> = {
  blue: "bg-[#e8f1fa] text-[#004b93]",
  sky: "bg-[#e0f2fe] text-[#0284c7]",
  navy: "bg-[#eff6ff] text-[#1d4ed8]",
  green: "bg-[#e8f1fa] text-[#004b93]",
  orange: "bg-[#fff7ed] text-[#c2410c]",
  purple: "bg-[#e0f2fe] text-[#0369a1]",
  red: "bg-[#fef2f2] text-[#b91c1c]",
};

export default function Stat({
  label,
  value,
  change,
  icon: Icon,
  tone,
}: StatProps) {
  return (
    <div className="rounded-xl border border-[#e2e8f0] bg-white p-4 shadow-[0_1px_2px_rgba(15,23,42,0.03)]">
      <div className="flex items-center justify-between">
        <div
          className={`flex h-8 w-8 items-center justify-center rounded-lg ${tones[tone] || tones.blue}`}
        >
          <Icon size={16} />
        </div>
        {change && (
          <span className="text-[10px] font-bold text-[#64748b]">{change}</span>
        )}
      </div>
      <p className="mt-4 text-[11px] font-semibold text-[#64748b]">{label}</p>
      <p className="mt-0.5 text-[25px] font-bold tracking-[-0.04em] text-[#0f172a]">{value}</p>
    </div>
  );
}


