'use client'

import { useEffect, useMemo, useState } from 'react'
import { Check, MapPin, Pencil, Plus, RefreshCw, Search, Trash2 } from 'lucide-react'
import { createZone, deleteZone, getZones, updateZone } from '../services/zones'
import { ConfirmDialog, Field, Modal } from './form-modal'

export interface Zone {
  id: string
  name: string
  location?: string
  companyId?: string
}

interface ZonesViewProps {
  onChange?: () => void
  onToast?: (message: string) => void
}

const getErrorMessage = (err: unknown, fallback: string) => {
  const message = (err as { response?: { data?: { message?: string | string[] } } })
    ?.response?.data?.message
  if (Array.isArray(message)) return message.join(', ')
  return message || fallback
}

export default function ZonesView({ onChange, onToast }: ZonesViewProps) {
  const [zones, setZones] = useState<Zone[]>([])
  const [loading, setLoading] = useState(true)
  const [error, setError] = useState('')
  const [search, setSearch] = useState('')

  // Formulario crear/editar
  const [showForm, setShowForm] = useState(false)
  const [editingZone, setEditingZone] = useState<Zone | null>(null)
  const [saving, setSaving] = useState(false)
  const [formError, setFormError] = useState('')

  // Confirmación de eliminación
  const [zoneToDelete, setZoneToDelete] = useState<Zone | null>(null)
  const [deleting, setDeleting] = useState(false)
  const [deleteError, setDeleteError] = useState('')

  const fetchZones = async () => {
    setLoading(true)
    setError('')
    try {
      const response = await getZones()
      const list: Zone[] = Array.isArray(response?.data)
        ? response.data
        : Array.isArray(response)
          ? response
          : []
      setZones(list)
    } catch (err) {
      console.error('Error fetching zones:', err)
      setError('No se pudieron cargar las zonas. Verifica la conexión.')
    } finally {
      setLoading(false)
    }
  }

  useEffect(() => {
    fetchZones()
  }, [])

  const filteredZones = useMemo(() => {
    const query = search.trim().toLowerCase()
    if (!query) return zones
    return zones.filter((z) => (z.name || '').toLowerCase().includes(query))
  }, [zones, search])

  const openCreate = () => {
    setEditingZone(null)
    setFormError('')
    setShowForm(true)
  }

  const openEdit = (zone: Zone) => {
    setEditingZone(zone)
    setFormError('')
    setShowForm(true)
  }

  const handleSubmit = async (event: React.FormEvent<HTMLFormElement>) => {
    event.preventDefault()
    const data = new FormData(event.currentTarget)
    const name = String(data.get('name') || '').trim()
    const location = String(data.get('location') || '').trim()
    if (!name || !location) return

    setSaving(true)
    setFormError('')
    try {
      if (editingZone) {
        await updateZone(editingZone.id, { name, location })
        onToast?.('Zona actualizada correctamente')
      } else {
        await createZone({ name, location })
        onToast?.('Zona creada correctamente')
      }
      setShowForm(false)
      setEditingZone(null)
      await fetchZones()
      onChange?.()
    } catch (err) {
      console.error('Error saving zone:', err)
      setFormError(getErrorMessage(err, 'No se pudo guardar la zona.'))
    } finally {
      setSaving(false)
    }
  }

  const handleDelete = async () => {
    if (!zoneToDelete) return
    setDeleting(true)
    setDeleteError('')
    try {
      await deleteZone(zoneToDelete.id)
      setZoneToDelete(null)
      onToast?.('Zona eliminada')
      await fetchZones()
      onChange?.()
    } catch (err) {
      console.error('Error deleting zone:', err)
      setDeleteError(
        getErrorMessage(
          err,
          'No se pudo eliminar la zona. Puede tener visitas asociadas.'
        )
      )
    } finally {
      setDeleting(false)
    }
  }

  return (
    <div className="flex flex-col gap-6">
      {/* Encabezado */}
      <div className="flex flex-col justify-between gap-4 sm:flex-row sm:items-end">
        <div>
          <p className="text-sm text-[#64748b]">
            Crea y administra las zonas o destinos de las visitas
          </p>
          <h2 className="mt-1 text-[27px] font-bold tracking-[-0.04em] text-[#0f172a]">
            Zonas
          </h2>
        </div>
        <div className="flex gap-2">
          <button
            onClick={fetchZones}
            disabled={loading}
            className="flex items-center justify-center gap-2 rounded-lg border border-[#cbd5e1] bg-white px-3.5 py-2.5 text-xs font-bold text-[#334155] shadow-sm transition hover:bg-[#f8fafc] disabled:opacity-50"
            title="Refrescar lista"
          >
            <RefreshCw size={15} className={loading ? 'animate-spin text-[#004b93]' : ''} />
            <span className="hidden sm:inline">Refrescar</span>
          </button>
          <button
            onClick={openCreate}
            className="flex items-center justify-center gap-2 rounded-lg bg-[#004b93] px-3.5 py-2.5 text-xs font-bold text-white shadow-sm transition hover:bg-[#003870]"
          >
            <Plus size={16} /> Nueva zona
          </button>
        </div>
      </div>

      <div className="rounded-xl border border-[#e2e8f0] bg-white p-5 shadow-[0_1px_2px_rgba(15,23,42,0.03)]">
        <div className="mb-5 flex flex-col justify-between gap-3 sm:flex-row sm:items-center">
          <div>
            <h3 className="text-sm font-bold text-[#0f172a]">Zonas registradas</h3>
            <p className="mt-1 text-xs text-[#64748b]">
              {zones.length} {zones.length === 1 ? 'zona' : 'zonas'} en total
            </p>
          </div>
          <div className="flex min-w-[220px] items-center gap-2 rounded-lg border border-[#cbd5e1] bg-white px-3 py-2 focus-within:border-[#004b93] focus-within:ring-2 focus-within:ring-[#004b93]/10">
            <Search size={15} className="text-[#94a3b8]" />
            <input
              value={search}
              onChange={(e) => setSearch(e.target.value)}
              placeholder="Buscar zona..."
              className="w-full bg-transparent text-xs outline-none placeholder:text-[#94a3b8]"
            />
          </div>
        </div>

        {error && (
          <div className="mb-4 rounded-lg bg-[#fef2f2] p-3 text-xs font-semibold text-[#b91c1c]">
            {error}
          </div>
        )}

        {loading ? (
          <div className="flex items-center justify-center gap-2 py-10 text-xs text-[#64748b]">
            <RefreshCw size={15} className="animate-spin text-[#004b93]" />
            Cargando zonas...
          </div>
        ) : filteredZones.length === 0 ? (
          <p className="py-10 text-center text-xs text-[#64748b]">
            {zones.length === 0
              ? 'Aún no hay zonas registradas. Crea la primera con "Nueva zona".'
              : 'No se encontraron zonas para la búsqueda.'}
          </p>
        ) : (
          <ul className="divide-y divide-[#f1f5f9]">
            {filteredZones.map((zone) => (
              <li key={zone.id} className="flex items-center gap-3 py-3">
                <div className="flex h-9 w-9 shrink-0 items-center justify-center rounded-lg bg-[#e8f1fa] text-[#004b93]">
                  <MapPin size={16} />
                </div>
                <div className="min-w-0 flex-1">
                  <p className="truncate text-sm font-semibold text-[#0f172a]">{zone.name}</p>
                  {zone.location && (
                    <p className="mt-0.5 truncate text-xs text-[#64748b]">{zone.location}</p>
                  )}
                </div>
                <button
                  onClick={() => openEdit(zone)}
                  className="rounded-lg p-2 text-[#64748b] transition hover:bg-[#e8f1fa] hover:text-[#004b93]"
                  title="Editar zona"
                  aria-label={`Editar zona ${zone.name}`}
                >
                  <Pencil size={15} />
                </button>
                <button
                  onClick={() => {
                    setDeleteError('')
                    setZoneToDelete(zone)
                  }}
                  className="rounded-lg p-2 text-[#64748b] transition hover:bg-[#fef2f2] hover:text-[#b91c1c]"
                  title="Eliminar zona"
                  aria-label={`Eliminar zona ${zone.name}`}
                >
                  <Trash2 size={15} />
                </button>
              </li>
            ))}
          </ul>
        )}
      </div>

      {showForm && (
        <Modal
          title={editingZone ? 'Editar zona' : 'Nueva zona'}
          onClose={() => setShowForm(false)}
        >
          <form onSubmit={handleSubmit} autoComplete="off" className="space-y-4">
            <Field
              label="Nombre de la zona"
              name="name"
              placeholder="Ej. Torre A"
              defaultValue={editingZone?.name}
            />
            <Field
              label="Ubicación"
              name="location"
              placeholder="Ej. Edificio central, piso 2"
              defaultValue={editingZone?.location}
            />
            {formError && (
              <div className="rounded-lg bg-[#fef2f2] p-3 text-xs font-semibold text-[#b91c1c]">
                {formError}
              </div>
            )}
            <button
              type="submit"
              disabled={saving}
              className="mt-2 flex w-full items-center justify-center gap-2 rounded-lg bg-[#004b93] py-3 text-sm font-bold text-white transition hover:bg-[#003870] disabled:cursor-not-allowed disabled:opacity-60"
            >
              <Check size={17} />
              {saving ? 'Guardando...' : editingZone ? 'Guardar cambios' : 'Crear zona'}
            </button>
          </form>
        </Modal>
      )}

      {zoneToDelete && (
        <ConfirmDialog
          title="Eliminar zona"
          message={
            <>
              ¿Seguro que quieres eliminar la zona <strong>{zoneToDelete.name}</strong>?
              Esta acción no se puede deshacer.
            </>
          }
          loading={deleting}
          error={deleteError}
          onConfirm={handleDelete}
          onCancel={() => setZoneToDelete(null)}
        />
      )}
    </div>
  )
}
