'use client'

import { X } from 'lucide-react'

export function Modal({
  title,
  children,
  onClose,
}: {
  title: string
  children: React.ReactNode
  onClose: () => void
}) {
  return (
    <div className="fixed inset-0 z-40 flex items-center justify-center bg-[#0f172a]/40 p-4 backdrop-blur-sm">
      <div
        role="dialog"
        aria-modal="true"
        className="max-h-[calc(100vh-2rem)] w-full max-w-md overflow-y-auto rounded-2xl border border-[#e2e8f0] bg-white p-6 shadow-xl"
      >
        <div className="mb-5 flex items-center justify-between">
          <h2 className="text-lg font-bold tracking-[-0.02em] text-[#0f172a]">{title}</h2>
          <button
            onClick={onClose}
            className="rounded-lg p-1.5 text-[#94a3b8] hover:bg-[#f1f5f9] hover:text-[#0f172a]"
            aria-label="Cerrar"
          >
            <X size={18} />
          </button>
        </div>
        {children}
      </div>
    </div>
  )
}

export function Field({
  label,
  name,
  placeholder,
  type = 'text',
  defaultValue,
}: {
  label: string
  name: string
  placeholder?: string
  type?: string
  defaultValue?: string
}) {
  return (
    <label className="block">
      <span className="mb-1.5 block text-xs font-bold text-[#334155]">
        {label}
      </span>
      <input
        required
        name={name}
        type={type}
        placeholder={placeholder}
        defaultValue={defaultValue}
        autoComplete="off"
        className="w-full rounded-lg border border-[#cbd5e1] bg-white px-3 py-2.5 text-sm outline-none transition placeholder:text-[#94a3b8] focus:border-[#004b93] focus:ring-2 focus:ring-[#004b93]/10"
      />
    </label>
  )
}

export function ConfirmDialog({
  title,
  message,
  confirmLabel = 'Eliminar',
  loadingLabel = 'Eliminando...',
  loading = false,
  error,
  onConfirm,
  onCancel,
}: {
  title: string
  message: React.ReactNode
  confirmLabel?: string
  loadingLabel?: string
  loading?: boolean
  error?: string
  onConfirm: () => void
  onCancel: () => void
}) {
  return (
    <Modal title={title} onClose={onCancel}>
      <p className="text-sm text-[#475569]">{message}</p>
      {error && (
        <div className="mt-4 rounded-lg bg-[#fef2f2] p-3 text-xs font-semibold text-[#b91c1c]">
          {error}
        </div>
      )}
      <div className="mt-6 flex justify-end gap-2">
        <button
          type="button"
          onClick={onCancel}
          className="rounded-lg border border-[#cbd5e1] px-4 py-2.5 text-xs font-bold text-[#334155] hover:bg-[#f8fafc]"
        >
          Cancelar
        </button>
        <button
          type="button"
          onClick={onConfirm}
          disabled={loading}
          className="rounded-lg bg-[#b91c1c] px-4 py-2.5 text-xs font-bold text-white hover:bg-[#991b1b] disabled:cursor-not-allowed disabled:opacity-60"
        >
          {loading ? loadingLabel : confirmLabel}
        </button>
      </div>
    </Modal>
  )
}
